objs={
'1': {'shift':(5,-5),'color':[(2,c) for c in range(13,18)]+[(3,13),(3,17),(4,13),(5,13),(6,13),(6,14)],'marks':[(2,12),(4,12),(4,17),(6,15)]},
'4': {'shift':(0,0),'color':[(r,c) for r in range(10,13) for c in range(11,14)],'marks':[(9,12),(11,10),(12,10),(13,12)]},
'5': {'shift':(3,-13),'color':[(9,18),(9,19),(10,18),(11,18),(12,18),(12,19)],'marks':[(9,20),(12,20)]},
'7': {'shift':(-4,-3),'color':[(16,11),(16,12),(17,11),(18,11),(18,15)]+[(19,c) for c in range(11,16)],'marks':[(16,10),(16,13),(17,15),(19,10)]},
'8': {'shift':(-14,6),'color':[(16,c) for c in range(3,6)]+[(17,3)]+[(18,c) for c in range(3,6)],'marks':[(16,6),(18,6)]}
}
grid=[[0]*22 for _ in range(22)]
for color,o in objs.items():
 dr,dc=o['shift']
 for r,c in o['color']:
  rr,cc=r+dr,c+dc
  if grid[rr][cc] not in (0,int(color)): print('overlap!',rr,cc,grid[rr][cc],color)
  grid[rr][cc]=int(color)
 for r,c in o['marks']:
  rr,cc=r+dr,c+dc
  if grid[rr][cc] not in (0,2): print('mark collision!',rr,cc,grid[rr][cc])
  grid[rr][cc]=2
print('\n'.join(' '.join(map(str,row)) for row in grid))
